DELETE FROM Diplomacy_Responses WHERE LeaderType='LEADER_MASAYA_KID' AND ResponseType IN
('RESPONSE_FIRST_GREETING','RESPONSE_GREETING_NEUTRAL_HELLO','RESPONSE_GREETING_HOSTILE_HELLO',
 'RESPONSE_DOW_GENERIC','RESPONSE_ATTACKED_HOSTILE','RESPONSE_DEFEATED','RESPONSE_PEACE_OFFER',
 'RESPONSE_TRADE_ACCEPT_ACCEPTABLE','RESPONSE_TRADE_REJECT_UNACCEPTABLE','RESPONSE_RESPONSE_TO_BEING_DENOUNCED');
INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_LEADER_MASAYA_KID_FIRSTGREETING_1','Hi! Have you ever flown from somewhere this high? Come on, I''ll show you the best launch point!'),
('TXT_KEY_LEADER_MASAYA_KID_GREETING_NEUTRAL_1','Perfect timing. I was just about to try one more flight.'),
('TXT_KEY_LEADER_MASAYA_KID_GREETING_HOSTILE_1','You don''t look like you came here to enjoy the view.'),
('TXT_KEY_LEADER_MASAYA_KID_DOW_1','If you''re going to hurt my friends, I''ll meet you in the sky.'),
('TXT_KEY_LEADER_MASAYA_KID_ATTACKED_1','All right. I''ll fly higher than anything you can throw at us!'),
('TXT_KEY_LEADER_MASAYA_KID_DEFEATED_1','I couldn''t reach it this time... but the sky will still be there tomorrow.'),
('TXT_KEY_LEADER_MASAYA_KID_PEACE_1','Let''s stop. Flying is better when everyone gets to come home.'),
('TXT_KEY_LEADER_MASAYA_KID_TRADE_ACCEPT_1','That sounds great!'),
('TXT_KEY_LEADER_MASAYA_KID_TRADE_REJECT_1','Hmm... that doesn''t feel fair.'),
('TXT_KEY_LEADER_MASAYA_KID_DENOUNCED_1','You can say that. I''m still going to fly.' );
